"use client";

import React from "react";

import { CardFrame, type CardCompositionProps } from "./CardFrame";
import bracketStyles from "../styles/CornerBrackets.module.css";
import styles from "./Card.module.css";

export type CardVariant = "default" | "featured" | "brackets" | "ghost";

export interface CardProps
  extends CardCompositionProps, Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** `featured` adds accent emphasis, `brackets` offset corner brackets, `ghost` a dashed transparent outline. */
  variant?: CardVariant;
}

const VARIANT_CLASSES: Record<CardVariant, string> = {
  default: "",
  featured: styles.featured,
  brackets: `${styles.bracketed} ${bracketStyles.brackets}`,
  ghost: styles.ghost,
};

export function Card({
  title,
  titleAs,
  titleClassName = "",
  variant = "default",
  className = "",
  children,
  ...props
}: CardProps) {
  return (
    <CardFrame
      className={`${styles.card} ${VARIANT_CLASSES[variant] ?? ""} ${className}`}
      data-variant={variant}
      title={title}
      titleAs={titleAs}
      titleClassName={`${styles.title} ${titleClassName}`.trim()}
      {...props}
    >
      {children}
    </CardFrame>
  );
}

.card {
  position: relative;
  border: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--bg-secondary) 88%, transparent);
  border-radius: 14px;
  padding: 1rem;
  box-shadow: var(--shadow-sm);
}

.featured {
  border-color: var(--accent-primary);
  box-shadow: var(--shadow-md);
}

/* Square corners so the offset brackets read as part of the frame. */
.bracketed {
  border-radius: 0;
  box-shadow: none;
}

.ghost {
  border-style: dashed;
  background: transparent;
  box-shadow: none;
}

.title {
  margin-bottom: 0.75rem;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 600;
}
